 Rigidbody2D Body(Component c){return (Rigidbody2D)pt.GetField("rb").GetValue(c);} void Move(Component c,Vector2 xy){c.transform.position+=(Vector3)(xy-Body(c).position);foreach(var b in c.GetComponentsInChildren<Rigidbody2D>()){b.velocity=Vector2.zero;b.angularVelocity=0;}Physics2D.SyncTransforms();}
