 object Read(BuildPlayer p,string n){return typeof(BuildPlayer).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(p);}
 IEnumerator Scene(bool highFan,bool equal){keys.Clear();UseAI=false;PlayerSkills.Enabled=false;AbilityMode.Enabled=true;AbilityMode.Reset();AbilityMode.Builds[0].Levels[1]=equal?4:highFan?8:0;AbilityMode.Builds[1].Levels[1]=equal?4:highFan?0:8;typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.4f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);fb=Body(fan);zb=Body(zhao);fp=fan.GetComponent<BuildPlayer>();zp=zhao.GetComponent<BuildPlayer>();ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;Move(fan,new Vector2(-3*scale,fb.position.y));Move(zhao,new Vector2(3*scale,zb.position.y));ball.position=new Vector2(0,9);ball.gravityScale=0;yield return new WaitForSeconds(.4f);GameAIMod.OnBallReset();}
 string Details(Component player){string s="";foreach(var c in player.GetComponentsInChildren<Collider2D>())if(c.IsTouching(ball.GetComponent<Collider2D>()))s+=c.name+";";return s;}
 bool BothBall(string part){return TouchesPart(fan,part)&&TouchesPart(zhao,part);}bool TouchesPart(Component p,string part){foreach(var c in p.GetComponentsInChildren<Collider2D>())if(c.IsTouching(ball.GetComponent<Collider2D>())&&(part=="feet"?(c.name.IndexOf("Leg",StringComparison.OrdinalIgnoreCase)>=0||c.name.IndexOf("Foot",StringComparison.OrdinalIgnoreCase)>=0):c.name==(part=="head"?"Head":"Body")))return true;return false;}
