 IEnumerator Duel(bool highFan,bool equal,string part){yield return Scene(highFan,equal);string name=part=="feet"?"R_LowLeg":part=="head"?"Head":"Body";Collider2D left=fan.transform.Find(name).GetComponent<Collider2D>(),right=zhao.transform.Find(name).GetComponent<Collider2D>();bool through=part!="body";float radius=ball.GetComponent<Collider2D>().bounds.extents.x;float y=part=="feet"?(float)Read(fp,"groundY")+radius+.02f:(left.bounds.center.y+right.bounds.center.y)*.5f;
 Move(fan,new Vector2(-.8f*scale,fb.position.y));Move(zhao,new Vector2(.8f*scale,zb.position.y));Physics2D.SyncTransforms();
 if(part=="feet"){float le=float.NegativeInfinity,re=float.PositiveInfinity;foreach(var c in fan.GetComponentsInChildren<Collider2D>())if(c.name.IndexOf("Leg",StringComparison.OrdinalIgnoreCase)>=0||c.name.IndexOf("Foot",StringComparison.OrdinalIgnoreCase)>=0)le=Mathf.Max(le,c.ClosestPoint(new Vector2(100,y)).x);foreach(var c in zhao.GetComponentsInChildren<Collider2D>())if(c.name.IndexOf("Leg",StringComparison.OrdinalIgnoreCase)>=0||c.name.IndexOf("Foot",StringComparison.OrdinalIgnoreCase)>=0)re=Mathf.Min(re,c.ClosestPoint(new Vector2(-100,y)).x);Move(fan,fb.position+Vector2.right*(-radius-le+.004f));Move(zhao,zb.position+Vector2.right*(radius-re-.004f));}
 else if(part=="chest"){Vector2 le=left.ClosestPoint(new Vector2(0,y)),re=right.ClosestPoint(new Vector2(0,y));Move(fan,fb.position+Vector2.right*((through?-radius:0)-le.x+.012f));Move(zhao,zb.position+Vector2.right*((through?radius:0)-re.x-.012f));}
 else {Move(fan,fb.position+new Vector2((through?-radius:0)-left.bounds.max.x+.012f,y-left.bounds.center.y));Move(zhao,zb.position+new Vector2((through?radius:0)-right.bounds.min.x-.012f,y-right.bounds.center.y));}
 ball.position=through?new Vector2(0,y):new Vector2(0,9);ball.velocity=Vector2.zero;ball.gravityScale=part=="feet"?1:0;Physics2D.SyncTransforms();float origin=(fb.position.x+zb.position.x)*.5f,dir=highFan?1:-1;BuildPlayer high=highFan?fp:zp,low=highFan?zp:fp;Component actor=highFan?fan:zhao;frames=0;ratio=1;stable=true;ahead=100;float contactShift=0,previousMiddle=origin;bool previousLinked=false;int contactSamples=0;
 keys.Add(ControlBindings.Get(true,GameControlAction.Right));keys.Add(ControlBindings.Get(false,GameControlAction.Left));for(int i=0;i<45;i++){yield return new WaitForFixedUpdate();bool linked=through?BothBall(part):high.InContest;float currentMiddle=(fb.position.x+zb.position.x)*.5f;if(previousLinked){contactShift+=dir*(currentMiddle-previousMiddle);contactSamples++;}previousMiddle=currentMiddle;previousLinked=linked;if(linked){frames++;ratio=high.ContactDrive(dir)/low.ContactDrive(-dir);}stable&=Joint(fan)<.5f&&Joint(zhao)<.5f&&!high.Staggered&&!low.Staggered;if(part=="feet")ahead=Mathf.Min(ahead,dir*(ball.position.x-Body(actor).position.x));}
 keys.Clear();measured=contactSamples>0?contactShift/(contactSamples*Time.fixedDeltaTime):0f;Move(highFan?zhao:fan,Body(actor).position+Vector2.right*dir*5*scale);yield return new WaitForFixedUpdate();released=Mathf.Abs(high.ContactDrive(dir)-1)<.001f&&!high.InContest&&!high.JumpBlocked;Debug.Log("ABILITY DUEL high="+actor.name+" part="+part+" equal="+equal+" contactRate="+measured+" contactFrames="+frames+" ratio="+ratio+" stable="+stable+" ahead="+ahead);}
 IEnumerator AirAndImmunity(bool highFan){
  yield return Scene(highFan,false);Component strong=highFan?fan:zhao,weak=highFan?zhao:fan;BuildPlayer high=highFan?fp:zp,low=highFan?zp:fp;float dir=highFan?1:-1;
  Collider2D a=strong.transform.Find("Body").GetComponent<Collider2D>(),b=weak.transform.Find("Body").GetComponent<Collider2D>();Move(strong,new Vector2(-dir*.4f*scale,Body(strong).position.y+3f*scale));Move(weak,new Vector2(Body(strong).position.x+dir*(a.bounds.extents.x+b.bounds.extents.x-.025f*scale),Body(strong).position.y));foreach(var limb in strong.GetComponentsInChildren<Rigidbody2D>())limb.velocity=Vector2.right*dir*3;foreach(var limb in weak.GetComponentsInChildren<Rigidbody2D>())limb.velocity=Vector2.right*-dir*3;ball.position=new Vector2(0,strong.transform.Find("Head").position.y+.2f*scale);ball.velocity=Vector2.zero;bool unbalanced=false,highSteady=true;float weakSpin=0,strongSpin=0,weakAngle=0,strongAngle=0,weakExcursion=0,strongExcursion=0,weakTravel=0,strongTravel=0,previousWeak=Body(weak).rotation,previousStrong=Body(strong).rotation;bool airContact=false;
  for(int i=0;i<10;i++){yield return new WaitForFixedUpdate();airContact|=high.InContest;weakTravel+=Mathf.Abs(Mathf.DeltaAngle(previousWeak,Body(weak).rotation));strongTravel+=Mathf.Abs(Mathf.DeltaAngle(previousStrong,Body(strong).rotation));previousWeak=Body(weak).rotation;previousStrong=Body(strong).rotation;weakAngle=Mathf.Abs(Mathf.DeltaAngle(Body(weak).rotation,0));strongAngle=Mathf.Abs(Mathf.DeltaAngle(Body(strong).rotation,0));weakExcursion=Mathf.Max(weakExcursion,weakAngle);strongExcursion=Mathf.Max(strongExcursion,strongAngle);unbalanced|=low.Staggered;highSteady&=!high.Staggered;weakSpin=Mathf.Max(weakSpin,Mathf.Abs(Body(weak).angularVelocity));strongSpin=Mathf.Max(strongSpin,Mathf.Abs(Body(strong).angularVelocity));}
  Check(airContact&&unbalanced&&highSteady&&(weakAngle>strongAngle+5f||weakExcursion>strongExcursion+5f||(weakExcursion>=10f&&weakTravel>strongTravel*1.5f))&&strongAngle<15f&&Joint(strong)<.5f&&Joint(weak)<.5f,"real aerial contact unbalances lower contest "+strong.name+" weakTravel="+weakTravel+" strongTravel="+strongTravel+" weakExcursion="+weakExcursion+" strongExcursion="+strongExcursion+" weakAngle="+weakAngle+" strongAngle="+strongAngle+" weakSpin="+weakSpin+" strongSpin="+strongSpin+" stagger="+unbalanced+" contact="+airContact+" highSteady="+highSteady+" highJoint="+Joint(strong)+" lowJoint="+Joint(weak));
  yield return Scene(highFan,false);strong=highFan?fan:zhao;weak=highFan?zhao:fan;high=highFan?fp:zp;low=highFan?zp:fp;AbilityMode.For(weak).Levels[1]=4;AbilityMode.For(strong).Levels[1]=6;AbilityMode.For(weak).Purchased=1<<3;a=strong.transform.Find("Body").GetComponent<Collider2D>();b=weak.transform.Find("Body").GetComponent<Collider2D>();Move(strong,new Vector2(-dir*.4f*scale,Body(strong).position.y));Move(weak,new Vector2(Body(strong).position.x+dir*(a.bounds.extents.x+b.bounds.extents.x-.025f*scale),Body(strong).position.y));bool immune=true;float distance=0,startX=Body(strong).position.x,actual=0;for(int i=0;i<25;i++){yield return new WaitForFixedUpdate();actual=Mathf.Max(actual,-dir*(Body(strong).position.x-startX));immune&=!high.Staggered;distance=Mathf.Max(distance,(float)Read(high,"knockDistance"));high.Pose();}
  Check(immune&&distance>0&&actual>.05f*scale&&((float[])Read(low,"effects"))[3]>0&&Joint(strong)<.5f,"higher contest ignores weak tackle imbalance but retains knockback "+strong.name+" distance="+distance+" actual="+actual);
 }
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=120;QualitySettings.vSyncCount=0;AudioListener.volume=0;yield return new WaitForSeconds(.2f);foreach(bool highFan in new bool[]{true,false})foreach(string part in new string[]{"body","feet","head"}){yield return Duel(highFan,true,part);float baseline=measured;int equalFrames=frames;yield return Duel(highFan,false,part);Check(frames>0&&equalFrames>0&&ratio>1.6f&&stable&&released&&(part=="feet"?ahead>0:measured>baseline+.06f*scale),(part=="feet"?"real foot contact retains front ball and full pressure ":"real differential pressure ")+(highFan?"Fan":"Zhao")+" "+part+" baseline="+baseline+" high="+measured+" frames="+frames+" ratio="+ratio);}
